    expect(in_array('Raid', $offered, true))->toBeTrue('offered: ' . json_encode($offered) . ' rejections: ' . json_encode($generation->rejections));

    $situation->session();

    $perception = app(PlayerPerceptionBuilder::class)->build($this->currentUserId);
    $diagnosis = json_encode([
        'slots' => $perception->fleetSlotsFree,
        'reports' => $perception->targetReports,
        'plan' => app(RaidPlanner::class)->plan($this->currentUserId, $reportId),
        'ships' => $this->planetService->getShipUnits()->toArray(),
    ]);
    $offered = array_map(static fn ($candidate): string => $candidate->type->name, app(CandidateActionFactory::class)
        ->create($perception)->candidates);
    expect($offered)->toContain('Raid', $diagnosis . '; ' . $situation->account());

    $situation->sessions(2)->expectMission('Attack');
});

